def threshold(price=10494.00368,cost=4000,cap=5850,rate=.1,life=20,start=2032):
 pv=sum(cap/5/(1+rate)**i for i in range(1,6));factor=sum(1/(1+rate)**(y-2026)for y in range(start,start+life));annual=pv/factor
 return dict(pv_capex=pv,benefit_factor=factor,annual=annual,kt=annual*1000/((price-cost)*.65)if price>cost else None)
d['thresholds']=[dict(name=n,**threshold(**args))for n,args in [('20 years from 2032',{}),('10 years from 2032',{'life':10}),('10 years from 2034',{'life':10,'start':2034}),('8% discount rate',{'rate':.08}),('12% discount rate',{'rate':.12}),('$3,000/t burden',{'cost':3000}),('$5,000/t burden',{'cost':5000}),('Combined stress',{'price':8500,'cap':7020,'start':2034})]]
d['frontier']=[dict(price=p,burden=c,**threshold(price=p,cost=c))for c in [3000,4000,5000]for p in [8500,9500,10494.00368,11500,13000]]
